def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    first = {"id": "b", "day": 9, "flagged": True}
    last = {"id": "b", "day": 2, "flagged": False}
    same_day = {"id": "a", "day": 2, "flagged": True}
    next_day = {"id": "a2", "day": 3, "flagged": True}
    assert dedupe_transcripts([first, next_day, last, same_day]) == [same_day, last, next_day]


def test_daily_flag_counts_uses_inclusive_range_and_fills_gaps():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,3,1", "g,4,1"])
    assert daily_flag_counts(events, 1, 3) == [2, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_and_ignores_empty_groups():
    events = parse_transcript_log(["a,1,1", "b,3,0", "c,3,"])
    groups = {"active": events, "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 1, "groups": 1}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_breaks_ties_by_name_and_excludes_empty_groups():
    groups = {"z": [{"flagged": True}], "none": [{"flagged": None}], "b": [], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "none"]


def test_flag_rate_by_group_sorts_keys_and_distinguishes_empty_from_zero():
